namespace SimplePZMapmaker.Core;
public static partial class HousingTemplates
{
 // These are original gameplay layouts, informed by the same documented regional building typologies.
 private static IEnumerable<Descriptor> RegionalDescriptors()=>[
  new("village-log-long","Northern longhouse","village","A wooden house with a long entrance hall connecting the living area, kitchen, and utility storage under a shared gabled roof.",24,16,1,0,[MuseumReference]),
  new("village-brick-cottage","Brick cottage with attic floor","village","Two residential levels: living room, kitchen, and study downstairs; three bedrooms and a bathroom upstairs. Stairs in a separate hall.",22,20,2,0,[IzbaReference]),
  new("village-farmstead","House with utility wing","village","A living area, entrance hall, and separate utility wing form a stepped outline and an open terrace.",28,24,1,0,[FarmReference,MuseumReference]),
  new("village-bathhouse","Village bathhouse","village","A changing room, washing room, utility room, and entrance vestibule. A compact wooden building with a hipped roof.",14,12,1,0,[FarmReference]),
  new("settlement-duplex","Village duplex","settlement","Two fully independent apartments, each with its own entrance, stairs, and upstairs bedrooms.",32,20,2,0,[SettlementReference]),
  new("settlement-row-four","Village terraced housing","settlement","Four independent two-story sections with separate entrances, kitchens, and internal stairs.",48,18,2,0,[SettlementReference]),
  new("settlement-clinic","Village clinic","settlement","Two levels: reception and offices along a shared corridor; staff rooms and patient wards upstairs.",28,28,2,0,[ClassicReference]),
  new("settlement-courtyard","Village courtyard house","settlement","Two residential wings around an open courtyard; a shared corridor and stairs beside the gate.",36,32,2,0,[SettlementReference,ClassicReference]),
  new("urban-compact-six","Compact six-story apartment block","urban","Two apartments per floor, a shared stair hall, and separate kitchens, bedrooms, and bathrooms. Six levels and a flat roof.",28,26,6,0,[PanelReference,TowerReference]),
  new("urban-perimeter-four","Urban courtyard apartment block","urban","Four levels in an enclosed block with an open courtyard, a through corridor, apartments in the side wings, and two staircases.",48,40,4,0,[ClassicReference,CornerReference]),
  new("urban-shop-house","Urban apartments above shops","urban","A spacious ground-floor shop with two smaller residential levels above it. Utility rooms and stairs are separate from the sales floor.",30,28,3,0,[ClassicReference]),
  new("urban-townhouse-row","Urban townhouse row","urban","Three independent three-story blocks with separate entrances; living rooms, kitchens, and bedrooms are distributed across the levels.",42,20,3,0,[ClassicReference,SettlementReference])
 ];
 private static void RegionalPlan(Building b,string id){
  switch(id){
   case "village-log-long":LongHouse(b);break;case "village-brick-cottage":Cottage(b);break;case "village-farmstead":Farmstead(b);break;case "village-bathhouse":Bathhouse(b);break;
   case "settlement-duplex":RowHouse(b,2,16,2);break;case "settlement-row-four":RowHouse(b,4,12,2);break;case "urban-townhouse-row":RowHouse(b,3,14,3);break;
   case "settlement-clinic":Clinic(b);break;case "settlement-courtyard":Courtyard(b,2);break;case "urban-perimeter-four":Courtyard(b,4);break;
   case "urban-compact-six":CompactSix(b);break;case "urban-shop-house":ShopHouse(b);break;
   default:throw new ArgumentException("Unknown regional layout.");
  }
 }
 private static void SetAppearance(Building b,string style,string roof){b.Design!.Style=style;b.Design.Material=VisualStyles.All[style].Material;b.Design.Roof=roof;b.Design.Shape="custom";}
 private static void LongHouse(Building b){SetAppearance(b,"cottage","gabled");var p=new Plan(b,0);var hall=p.Room("hall",0,10,24,6);var living=p.Room("livingroom",0,0,10,10);var kitchen=p.Room("kitchen",10,0,6,10);var store=p.Room("storage",16,0,8,10);p.Join(hall,living);p.Join(hall,kitchen);p.Join(hall,store);p.Entrance(12,16,"n");p.Finish();}
 private static void Cottage(Building b){SetAppearance(b,"brick","gabled");for(var z=0;z<2;z++){var p=new Plan(b,z);var hall=p.Room("hall",8,0,6,20);var a=p.Room(z==0?"livingroom":"bedroom",0,0,8,12);var kitchen=p.Room(z==0?"kitchen":"bedroom",14,0,8,12);var bath=p.Room("bathroom",0,12,8,8);var office=p.Room(z==0?"office":"bedroom",14,12,8,8);foreach(var room in new[]{a,kitchen,bath,office})p.Join(hall,room);if(z==0){p.Stairs(10,3);p.Entrance(11,0,"n");}p.Finish();}}
 private static void Farmstead(Building b){SetAppearance(b,"cottage","gabled");var p=new Plan(b,0);var living=p.Room("livingroom",0,0,10,10);var kitchen=p.Room("kitchen",10,0,8,10);var hall=p.Room("hall",0,10,18,6);var bedroom=p.Room("bedroom",0,16,12,8);var bath=p.Room("bathroom",12,16,6,8);var store=p.Room("storage",18,0,10,10);var work=p.Room("garage",18,10,10,6);var terrace=p.Room("balcony",18,16,6,4);p.Join(hall,living);p.Join(hall,kitchen);p.Join(hall,bedroom);p.Join(hall,bath);p.Join(kitchen,store);p.Join(hall,work);p.Join(store,work);p.Join(work,terrace);p.Entrance(21,20,"n");p.Finish();}
 private static void Bathhouse(Building b){SetAppearance(b,"cottage","hipped");var p=new Plan(b,0);var hall=p.Room("hall",0,8,14,4);var change=p.Room("livingroom",0,0,6,8);var wash=p.Room("bathroom",6,0,5,8);var utility=p.Room("storage",11,0,3,8);p.Join(hall,change);p.Join(hall,wash);p.Join(hall,utility);p.Entrance(7,12,"n");p.Finish();}
 private static void RowHouse(Building b,int sections,int width,int levels){SetAppearance(b,sections==4?"modern":"brick",levels==3?"flat":"gabled");for(var z=0;z<levels;z++){var p=new Plan(b,z);for(var section=0;section<sections;section++){var x=section*width;var core=p.Room("hall",x+width-4,0,4,b.Height);var body=width-4;var living=p.Room(z==0?"livingroom":"bedroom",x,0,body,b.Height/2);var kitchen=p.Room(z==0?"kitchen":"bedroom",x,b.Height/2,body,b.Height/2-4);var bathroom=p.Room("bathroom",x,b.Height-4,body,4);p.Join(core,living);p.Join(core,kitchen);p.Join(core,bathroom);if(z<levels-1)p.Stairs(x+width-3,3);if(z==0)p.Entrance(x+width-2,0,"n");}p.Finish();}}
 private static void Clinic(Building b){b.Kind="clinic";SetAppearance(b,"brick","hipped");for(var z=0;z<2;z++){var p=new Plan(b,z);var core=p.Room("hall",11,0,6,28);foreach(var x in new[]{0,17}){p.Join(core,p.Room(z==0?"office":"medical",x,0,11,10));p.Join(core,p.Room("medical",x,10,11,10));p.Join(core,p.Room(x==0?"bathroom":"storage",x,20,11,8));}if(z==0){p.Stairs(13,3);p.Entrance(14,0,"n");}p.Finish();}}
 private static void CompactSix(Building b){SetAppearance(b,"modern","flat");for(var z=0;z<6;z++){var p=new Plan(b,z);var core=p.Room("hall",11,0,6,26);foreach(var x in new[]{0,17}){var hall=p.Room("hall",x,0,11,4);var living=p.Room("livingroom",x,4,11,10);var bedroom=p.Room("bedroom",x,14,11,6);var kitchen=p.Room("kitchen",x,20,6,6);var bath=p.Room("bathroom",x+6,20,5,6);p.Join(core,hall);p.Join(hall,living);p.Join(living,bedroom);p.Join(bedroom,kitchen);p.Join(kitchen,bath);}if(z<5)p.Stairs(13,4);if(z==0)p.Entrance(14,0,"n");p.Finish();GreyFacade(b.Design!.Floors[z]);}}
 private static void Courtyard(Building b,int levels){SetAppearance(b,"brick","flat");var edge=8;for(var z=0;z<levels;z++){var p=new Plan(b,z);var core=p.Code("hall");p.Fill(core,0,0,b.Width,edge);p.Fill(core,0,b.Height-edge,b.Width,edge);p.Fill(core,edge-2,edge,2,b.Height-2*edge);p.Fill(core,b.Width-edge,edge,2,b.Height-2*edge);
    foreach(var x in new[]{0,b.Width-edge+2}){var available=b.Height-2*edge;CourtyardFlat(p,x,edge,available/2,x==0,core);CourtyardFlat(p,x,edge+available/2,available-available/2,x==0,core);}
    if(z<levels-1){p.Stairs(10,2,"w");if(levels==4)p.Stairs(b.Width-15,b.Height-5,"w");}if(z==0){p.Entrance(b.Width/2,0,"n");if(levels==4)p.Entrance(b.Width/2,b.Height,"n");}p.Finish();}}
 private static void CourtyardFlat(Plan p,int x,int y,int h,bool left,char core){var near=left?x+3:x;var far=left?x:x+3;var split=h/2;var living=p.Room("livingroom",x,y,6,split);var bedroom=p.Room("bedroom",near,y+split,3,h-split);var kitchen=p.Room("kitchen",far,y+split,3,(h-split)/2);var bath=p.Room("bathroom",far,y+split+(h-split)/2,3,h-split-(h-split)/2);p.Join(core,living);p.Join(living,bedroom);p.Join(living,kitchen);p.Join(kitchen,bath);}
 private static void ShopHouse(Building b){SetAppearance(b,"brick","flat");var ground=new Plan(b,0);var core=ground.Room("hall",12,0,6,28);var retail=ground.Room("conveniencestore",0,0,12,20);var retail2=ground.Room("conveniencestore",18,0,12,20);var store=ground.Room("storage",0,20,12,8);var office=ground.Room("office",18,20,12,8);ground.Join(core,retail);ground.Join(core,retail2);ground.Join(retail,store);ground.Join(retail2,office);ground.Stairs(14,4);ground.Entrance(15,0,"n");ground.Finish();
  for(var z=1;z<3;z++){var p=new Plan(b,z);var hall=p.Room("hall",12,0,6,24);foreach(var x in new[]{2,18}){var living=p.Room("livingroom",x,0,10,12);var near=x==2?x+5:x;var far=x==2?x:x+5;var kitchen=p.Room("kitchen",far,12,5,12);var bedroom=p.Room("bedroom",near,12,5,8);var bathroom=p.Room("bathroom",near,20,5,4);p.Join(hall,living);p.Join(living,kitchen);p.Join(hall,bedroom);p.Join(bedroom,bathroom);}if(z==1)p.Stairs(14,4);p.Finish();}
 }
}
